sys_script_include.script:
var CPMScope = Class.create();
CPMScope.prototype = {
  MAX_DEPTH: 3,    // relationship levels followed
  MAX_ITEMS: 100,  // safety limit

  initialize: function() {
    this.K = new CPMConst();
    this.T = this.K.TABLE;
  },

  // components of a CI as { id: depth }
  componentsOf: function(rootId) {
    var found = {};
    var seen = {};
    var level = [rootId];
    var count = 0;
    seen[rootId] = true;

    for (var depth = 1; depth <= this.MAX_DEPTH && level.length; depth++) {
      var next = [];
      var rel = new GlideRecord(this.T.RELATION);
      rel.addQuery('parent', 'IN', level.join(','));
      rel.query();
      while (rel.next()) {
        var child = rel.getValue('child');
        if (seen[child]) continue;
        seen[child] = true;
        found[child] = depth;
        next.push(child);
        if (++count >= this.MAX_ITEMS) return found;
      }
      level = next;
    }
    return found;
  },

  // one sentence listing the components today, frozen into the evidence at approval
  snapshot: function(rootId) {
    var ids = Object.keys(this.componentsOf(rootId));
    if (!ids.length) return 'No component was related to this CI in the CMDB at the time of approval.';

    var parts = [];
    var ci = new GlideRecord(this.T.CI);
    ci.addQuery('sys_id', 'IN', ids.join(','));
    ci.orderBy('name');
    ci.query();
    while (ci.next()) parts.push(ci.getDisplayValue() + ' (' + ci.getDisplayValue('sys_class_name') + ')');

    var text = 'Components at approval (' + parts.length + '): ' + parts.join(', ');
    return text.length > 3900 ? text.substring(0, 3897) + '...' : text;
  },

  type: 'CPMScope'
};
